\set ON_ERROR_STOP on
begin;
insert into auth.users(id,email,email_confirmed_at) select ('20000000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i=5 then 'u1@test.invalid' else 'u'||i||'@test.invalid' end,now() from generate_series(1,7)i;
insert into affiliate_admins(user_id) values('20000000-0000-4000-8000-000000000007');
set role service_role;
do $$declare a uuid;b uuid;u uuid;v jsonb;p jsonb;ap uuid;py uuid; n int;
begin
 a:=(affiliate_command('20000000-0000-4000-8000-000000000001','activate','{"code":"edge-a","display_name":"A","accept_terms":true,"terms_version":"2026-09-07"}')->>'id')::uuid;
 b:=(affiliate_command('20000000-0000-4000-8000-000000000002','activate','{"code":"edge-b","display_name":"B","paypal_email":"b@test.invalid","accept_terms":true,"terms_version":"2026-09-07"}')->>'id')::uuid;
 begin perform affiliate_command('20000000-0000-4000-8000-000000000003','activate','{"code":"edge-a","display_name":"duplicate","accept_terms":true,"terms_version":"2026-09-07"}'); raise exception 'duplicate code accepted'; exception when unique_violation then null; end;
 perform affiliate_command('20000000-0000-4000-8000-000000000001','track','{"code":"edge-a","destination":"/","token_hash":"self"}');
 if exists(select from affiliate_referrals where user_id='20000000-0000-4000-8000-000000000001') then raise exception 'self attribution allowed'; end if;
 perform affiliate_command('20000000-0000-4000-8000-000000000005','track','{"code":"edge-a","destination":"/","token_hash":"same-email"}');
 if exists(select from affiliate_referrals where user_id='20000000-0000-4000-8000-000000000005') then raise exception 'same-email attribution allowed'; end if;
 perform affiliate_command(null,'track','{"code":"edge-a","destination":"/tactics?chunk=25","token_hash":"expired"}');
 update affiliate_visitors set expires_at=now()-interval '1 second' where token_hash='expired';
 perform affiliate_command('20000000-0000-4000-8000-000000000003','bind','{"token_hash":"expired"}');
 if exists(select from affiliate_referrals where user_id='20000000-0000-4000-8000-000000000003') then raise exception 'expired attribution allowed'; end if;
 v:=affiliate_command('20000000-0000-4000-8000-000000000003','checkout','{"period":"monthly","normal_plan":"P-N","discount_plan":"P-D"}');
 if v->>'discount_bps'<>'0' then raise exception 'nonreferral discount'; end if;
 begin perform affiliate_command('20000000-0000-4000-8000-000000000007','prepare_payout',jsonb_build_object('id',b,'reason','below threshold')); raise exception 'threshold ignored'; exception when others then if sqlerrm='threshold ignored' then raise; end if; end;
 perform affiliate_command('20000000-0000-4000-8000-000000000002','apply','{"tier":2,"title":"FM","profile_url":"https://ratings.fide.com/profile/1"}');
 select id into ap from affiliate_applications where affiliate_id=b;
 if (select tier from affiliate_accounts where id=b)<>1 then raise exception 'pending application promoted'; end if;
 perform affiliate_command('20000000-0000-4000-8000-000000000007','review',jsonb_build_object('id',ap,'approve',true,'reason','Verified test profile'));
 if (select tier from affiliate_accounts where id=b)<>2 then raise exception 'title approval failed'; end if;
 u:='20000000-0000-4000-8000-000000000004';
 perform affiliate_command(u,'track','{"code":"edge-b","destination":"/pricing","token_hash":"buyer4"}');
 p:=jsonb_build_object('kind','payment','payment_id','EDGEPAY','event_id','EDGE-EVENT','user_id',u,'subscription_id','I-EDGE','currency','USD','gross_minor',50000,'tax_minor',0,'occurred_at',clock_timestamp());
 -- A later click received before a delayed webhook cannot steal the earlier payment.
 perform affiliate_command(u,'track','{"code":"edge-a","destination":"/pricing","token_hash":"buyer4"}');
 perform affiliate_record_payment(p);
 if (select affiliate_id from affiliate_referrals where user_id=u)<>b then raise exception 'late click stole conversion'; end if;
 update affiliate_commissions set hold_until=now()-interval '30 days' where payment_id='EDGEPAY';
 py:=(affiliate_command('20000000-0000-4000-8000-000000000007','prepare_payout',jsonb_build_object('id',b,'reason','monthly')) ->>'id')::uuid;
 v:=affiliate_command('20000000-0000-4000-8000-000000000007','payout_items',jsonb_build_object('id',py));
 if v->>'total'<>'1' then raise exception 'payout item missing'; end if;
 perform affiliate_record_payment(jsonb_build_object('kind','reversal','payment_id','EDGEPAY','event_id','ER1','reversal_id','ER1','user_id',u,'currency','USD','gross_minor',50000,'reason','full refund'));
 if (select status from affiliate_payouts where id=py)<>'cancelled' or (select status from affiliate_commissions where payment_id='EDGEPAY')<>'reversed' then raise exception 'prepared payout survived refund'; end if;
 perform affiliate_record_payment(jsonb_build_object('kind','reversal','payment_id','EDGEPAY','event_id','ER1-DUP','reversal_id','ER1','user_id',u,'currency','USD','gross_minor',50000,'reason','duplicate full refund'));
 if (select count(*) from affiliate_reversals where payment_id='EDGEPAY')<>1 then raise exception 'duplicate refund'; end if;
 perform affiliate_command('20000000-0000-4000-8000-000000000002','dashboard');
 if (select status from affiliate_commissions where payment_id='EDGEPAY')<>'reversed' then raise exception 'reversed commission cleared'; end if;
 v:=affiliate_command(u,'checkout','{"period":"monthly","normal_plan":"P-N","discount_plan":"P-D"}');
 if v->>'discount_bps'<>'0' then raise exception 'refund reset discount eligibility'; end if;
 perform affiliate_command('20000000-0000-4000-8000-000000000007','adjust',jsonb_build_object('id',b,'amount_minor',4999,'reason','private adjustment note'));
 update affiliate_commissions set hold_until=now()-interval '1 second' where affiliate_id=b and status='pending';
 begin perform affiliate_command('20000000-0000-4000-8000-000000000007','prepare_payout',jsonb_build_object('id',b,'reason','49.99 rolls over')); raise exception '49.99 paid'; exception when others then if sqlerrm='49.99 paid' then raise; end if; end;
 perform affiliate_command('20000000-0000-4000-8000-000000000007','adjust',jsonb_build_object('id',b,'amount_minor',1,'reason','threshold cent'));
 update affiliate_commissions set hold_until=now()-interval '1 second' where affiliate_id=b and status='pending';
 v:=affiliate_command('20000000-0000-4000-8000-000000000002','dashboard');
 if v::text like '%private adjustment note%' then raise exception 'private admin note leaked'; end if;
 v:=affiliate_command('20000000-0000-4000-8000-000000000007','prepare_payout',jsonb_build_object('id',b,'reason','exact threshold'));
 if v->>'amount_minor'<>'5000' then raise exception '50.00 threshold failed'; end if;
 u:='20000000-0000-4000-8000-000000000006';
 perform affiliate_command(u,'track','{"code":"edge-a","destination":"/pricing","token_hash":"taxbuyer"}');
 perform affiliate_record_payment(jsonb_build_object('kind','payment','payment_id','TAXPAY','event_id','TAX-EVENT','user_id',u,'subscription_id','I-TAX','currency','USD','gross_minor',10000,'tax_minor',1000,'occurred_at',clock_timestamp()));
 perform affiliate_record_payment(jsonb_build_object('kind','reversal','payment_id','TAXPAY','event_id','TAX-R','reversal_id','TAX-R','user_id',u,'currency','USD','gross_minor',1000,'refund_tax_minor',1000,'reason','tax-only provider refund'));
 if (select reversed_minor from affiliate_commissions where payment_id='TAXPAY')<>0 then raise exception 'tax-only refund incorrectly reduced net revenue commission'; end if;
 raise notice 'PASS: duplicate code, self/same-email, expiry, non-referral, 49.99 rollover / 50.00 payout, verified upgrade, late-webhook attribution, prepared payout reversal, duplicate refund, no discount reset, private notes and tax-only refund';
end $$;
reset role;
rollback;
